import csv
from datetime import datetime
from decimal import Decimal, getcontext

getcontext().prec = 2

def is_valid_transaction(row):
    try:
        return row['status'] == 'SUCCESS' and Decimal(row['amount']) >= 0
    except (KeyError, ValueError):
        return False

def process_csv(file_path):
    transactions = {}
    with open(file_path, newline='') as csvfile:
        reader = csv.DictReader(csvfile)
        for row in reader:
            tx_id = row['tx_id']
            timestamp = datetime.fromisoformat(row['timestamp'])
            if tx_id not in transactions or timestamp > transactions[tx_id]['timestamp']:
                transactions[tx_id] = row

    valid_count = 0
    total_valid_amount = Decimal('0.00')
    failed_count = 0

    for tx_id, row in transactions.items():
        if is_valid_transaction(row):
            valid_count += 1
            total_valid_amount += Decimal(row['amount'])
        elif row['status'] == 'FAILED':
            failed_count += 1

    return {
        'total_valid_amount': round(total_valid_amount, 2),
        'valid_count': valid_count,
        'failed_count': failed_count
    }

def main():
    import sys
    if len(sys.argv) != 2:
        sys.stderr.write('Usage: python reconcile.py <csv_file>
')
        sys.exit(1)

    try:
        result = process_csv(sys.argv[1])
        print(result)
    except Exception as e:
        sys.stderr.write(f'Error processing file: {e}
')
